namespace QuantForge.Core;
public sealed record NativeValidationDashboard(bool AndroidBuilt,bool AndroidDeviceAccepted,bool WindowsBuilt,bool WindowsValidated,bool StableEligible,IReadOnlyList<string> NextActions);
public static class NativeValidationDashboardRules{public static NativeValidationDashboard Create(ReleaseValidationMatrix android,ReleaseValidationMatrix windows){var next=new List<string>();if(!android.NativeBuildValidated)next.Add("build-android-apk");else if(!android.DeviceAccepted)next.Add("test-android-device");if(!windows.NativeBuildValidated)next.Add("build-windows");else if(!windows.DeviceAccepted)next.Add("test-windows");return new(android.NativeBuildValidated,android.DeviceAccepted,windows.NativeBuildValidated,windows.DeviceAccepted,android.StableEligible&&windows.StableEligible,next);}}
